INSERT INTO boe_inject.unit_version_stage (id,unit_id,body,valid_from,evidence_instrument,evidence_url,evidence_quote) VALUES
('boe26-953fd7aadc5794a1d74311fd','cmpz5u0qx00qjcwg26ewbykdq','( يجتمع  مجلس الإدارة  مرة كل ثلاثة أشهر، ويجوز عند الضرورة أن يجتمع أكثر من ذلك بدعوة من رئيسه، أو بناء على طلب أربعة من أعضائه أو من الأمين العام للدارة ).','1983-07-30','مرسوم ملكي رقم م/51 وتاريخ 20/10/1403هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0057fd8d-8ad4-48f9-b02f-a9a700f16a48/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/51) وتاريخ 20/ 10/ 1403هـ ، لتكون بالنص التالي:

( يجتمع  مجلس الإدارة  مرة كل ثلاثة أشهر، ويجوز عند الضرورة أن يجتمع أكثر من ذلك بدعوة من رئيسه، أو بناء على طلب أربعة من أعضائه أو من الأمين العام للدارة ).'),
('boe26-9f405f57662d0ef67a39f7af','cmpz5u0wo00qlcwg2rg0ernu5','(يعتبر الاجتماع قانونياً بحضور خمسة أعضاء على الأقل ، وتصدر القرارات بالأكثرية المطلقة ، وفي حالة التساوي يرجح جانب الرئيس).','1983-07-30','مرسوم ملكي رقم م/51 وتاريخ 20/10/1403هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0057fd8d-8ad4-48f9-b02f-a9a700f16a48/1','تم تعديل هذه المادة بموجب   المرسوم الملكي  رقم (م/51) وتاريخ 20/ 10/ 1403هـ ، لتكون بالنص التالي:

(يعتبر الاجتماع قانونياً بحضور خمسة أعضاء على الأقل ، وتصدر القرارات بالأكثرية المطلقة ، وفي حالة التساوي يرجح جانب الرئيس).'),
('boe26-2c5b013bbaa2853f247f1997','cmpzcv89q0amlvtrk1tflfj16','العمل حق للمواطن، لا يجوز لغيره ممارسته إلا بعد توافر الشروط المنصوص عليها في هذا النظام، والمواطنون متساوون في حق العمل دون أي تمييز على أساس الجنس أو الإعاقة أو السن أو أي شكل من أشكال التمييز الأخرى، سواءً أثناء أداء العمل أو عند التوظيف أو الإعلان عنه','2019-07-30','مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 / 1440هـ، لتكون بالنص الآتي: "العمل حق للمواطن، لا يجوز لغيره ممارسته إلا بعد توافر الشروط المنصوص عليها في هذا النظام، والمواطنون متساوون في حق العمل دون أي تمييز على أساس الجنس أو الإعاقة أو السن أو أي شكل من أشكال التمييز الأخرى، سواءً أثناء أداء العمل أو عند التوظيف أو الإعلان عنه".'),
('boe26-eaeb16dbc2abe9d2359dc97b','cmpzcv89q0amnvtrk6ng1ueja','تسري أحكام هذا النظام على الآتي :

1 - كل عقد عمل يلتزم بمقتضاه أي شخص بالعمل لمصلحة صاحب عمل وتحت إدارته أو إشرافه؛ مقابل أجر.

2 - عمال الحكومة والهيئات والمؤسسات العامة، بمن فيهم الذين يشتغلون في المراعي أو الزراعة.

3 - عمال المؤسسات الخيرية.

4 - عقود التأهيل والتدريب مع غير العاملين لدى صاحب العمل في حدود الأحكام الخاصة المنصوص عليها في هذا النظام.

5 - العاملين بعض الوقت في حدود ما يتعلق بالسلامة والصحة المهنية وإصابات العمل وما يقرره الوزير','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"تسري أحكام هذا النظام على الآتي :

1 - كل عقد عمل يلتزم بمقتضاه أي شخص بالعمل لمصلحة صاحب عمل وتحت إدارته أو إشرافه؛ مقابل أجر.

2 - عمال الحكومة والهيئات والمؤسسات العامة، بمن فيهم الذين يشتغلون في المراعي أو الزراعة.

3 - عمال المؤسسات الخيرية.

4 - عقود التأهيل والتدريب مع غير العاملين لدى صاحب العمل في حدود الأحكام الخاصة المنصوص عليها في هذا النظام.

5 - العاملين بعض الوقت في حدود ما يتعلق ب'),
('boe26-a22944c140f259376eff54e2','cmpzcv89s0apbvtrk3oc3pkzr','تنظم ساعات العمل وفترات الراحة خلال اليوم، بحيث لا يعمل العامل أكثر من خمس ساعات متتالية دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة خلال مجموع ساعات العمل، وبحيث لا يبقى العامل في مكان العمل أكثر من اثنتي عشرة ساعة في اليوم الواحد','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"تنظم ساعات العمل وفترات الراحة خلال اليوم، بحيث لا يعمل العامل أكثر من خمس ساعات متتالية دون فترة للراحة والصلاة والطعام لا تقل عن نصف ساعة في المرة الواحدة خلال مجموع ساعات العمل، وبحيث لا يبقى العامل في مكان العمل أكثر من اثنتي عشرة ساعة في اليوم الواحد".'),
('boe26-3b60dfd76c6151bbea444ae1','cmpzcv89r0ao0vtrkqqat4vwl','لا يجوز وضع العامل تحت التجربة أكثر من مرة واحدة لدى صاحب عمل واحد.
واستثناء من ذلك يجوز باتفاق طرفي العقد - كتابة - إخضاع العامل لفترة تجربة أخرى بشرط أن تكون في مهنة أخرى أو عمل آخر، أو أن يكون قد مضى على انتهاء علاقة العامل بصاحب العمل مدة لا تقل عن ستة أشهر. وإذا أنهي العقد خلال فترة التجربة فإن أيًّا من الطرفين لا يستحق تعويضاً، كما لا يستحق العامل مكافأة نهاية الخدمة عن ذلك','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"لا يجوز وضع العامل تحت التجربة أكثر من مرة واحدة لدى صاحب عمل واحد.
واستثناء من ذلك يجوز باتفاق طرفي العقد - كتابة - إخضاع العامل لفترة تجربة أخرى بشرط أن تكون في مهنة أخرى أو عمل آخر، أو أن يكون قد مضى على انتهاء علاقة العامل بصاحب العمل مدة لا تقل عن ستة أشهر. وإذا أنهي العقد خلال فترة التجربة فإن أيًّا من الطرفين لا يستحق تعويضاً، كما لا يستحق العامل مكافأة نهاية الخدمة عن ذلك".'),
('boe26-66e4f9dcd62f665d905e6457','cmpzcv89r0ao1vtrkcfdvcmdl','1 - ينتهي عقد العمل المحدد المدة بانقضاء مدته، فإذا استمر طرفاه في تنفيذ عُدَّ العقدُ مجدداً لمدة غير محددة. مع مراعاة ما نصت عليه المادة (السابعة والثلاثون) من هذا النظام بالنسبة إلى غير السعوديين.

2 - إذا تضمن العقد المحدد المدة شرطاً يقضي بتجديده لمدة مماثلة أو لمدة محددة، فإنه يتجدد للمدة المتفق عليها. فإن تعدد التجديد ثلاث مرات متتالية، أو بلغت مدة العقد الأصلي مع مدة التجديد أربع سنوات أيهما أقل واستمر الطرفان في تنفيذه؛ تحوّل العقد إلى عقد غير محدد المدة','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - ينتهي عقد العمل المحدد المدة بانقضاء مدته، فإذا استمر طرفاه في تنفيذ عُدَّ العقدُ مجدداً لمدة غير محددة. مع مراعاة ما نصت عليه المادة (السابعة والثلاثون) من هذا النظام بالنسبة إلى غير السعوديين.

2 - إذا تضمن العقد المحدد المدة شرطاً يقضي بتجديده لمدة مماثلة أو لمدة محددة، فإنه يتجدد للمدة المتفق عليها. فإن تعدد التجديد ثلاث مرات متتالية، أو بلغت مدة العقد الأصلي مع مدة التجديد أربع سنوات أيه'),
('boe26-b5745303369ba6be11526d64','cmpzcv89r0ao4vtrkrvs791oo','1 - لا يجوز لصاحب العمل أن ينقل العامل بغير موافقته – كتابةً – من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته.

2 - لصاحب العمل - في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة – تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته، على أن يتحمل صاحب العمل تكاليف انتقال العامل وإقامته خلال تلك المدة','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - لا يجوز لصاحب العمل أن ينقل العامل بغير موافقته – كتابةً – من مكان عمله الأصلي إلى مكان آخر يقتضي تغيير محل إقامته.

2 - لصاحب العمل - في حالات الضرورة التي قد تقتضيها ظروف عارضة ولمدة لا تتجاوز ثلاثين يوماً في السنة – تكليف العامل بعمل في مكان يختلف عن المكان المتفق عليه دون اشتراط موافقته، على أن يتحمل صاحب العمل تكاليف انتقال العامل وإقامته خلال تلك المدة".'),
('boe26-9c22b5943b83229466b90583','cmpzcv89r0aoavtrk0bhl4w2m','يلتزم صاحب العمل عند انتهاء عقد العمل بما يأتي :

1 - أن يعطي العامل – بناءً على طلبه – شهادة خدمة دون مقابل، يوضح فيها تاريخ التحاقه بالعمل، وتاريخ انتهاء علاقته به، ومهنته، ومقدار أجره الأخير. ولا يجوز لصاحب العمل تضمين الشهادة ما قد يسيء إلى سمعة العامل أو يقلل من فرص العمل أمامه.

2 - أن يعيد إلى العامل جميع ما أودعه لديه من شهادات أو وثائق','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"يلتزم صاحب العمل عند انتهاء عقد العمل بما يأتي :

1 - أن يعطي العامل – بناءً على طلبه – شهادة خدمة دون مقابل، يوضح فيها تاريخ التحاقه بالعمل، وتاريخ انتهاء علاقته به، ومهنته، ومقدار أجره الأخير. ولا يجوز لصاحب العمل تضمين الشهادة ما قد يسيء إلى سمعة العامل أو يقلل من فرص العمل أمامه.

2 - أن يعيد إلى العامل جميع ما أودعه لديه من شهادات أو وثائق".'),
('boe26-d5ae388b0f5dca5820313f92','cmpzcv89r0aojvtrk29f88ich','يجب على صاحب العمل أن يكتب الغرامات التي يوقعها على العامل في سجل خاص، مع بيان اسم العامل ومقدار أجره ومقدار الغرامة وسبب توقيعها وتاريخ ذلك. ولا يجوز التصرف في الغرامات إلا فيما يعود بالنفع على عمال المنشأة، على أن يكون التصرف بهذه الغرامات من قبل اللجنة العمالية في المنشأة، وفي حالة عدم وجود لجنة يكون التصرف في الغرامات بموافقة الوزارة','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"يجب على صاحب العمل أن يكتب الغرامات التي يوقعها على العامل في سجل خاص، مع بيان اسم العامل ومقدار أجره ومقدار الغرامة وسبب توقيعها وتاريخ ذلك. ولا يجوز التصرف في الغرامات إلا فيما يعود بالنفع على عمال المنشأة، على أن يكون التصرف بهذه الغرامات من قبل اللجنة العمالية في المنشأة، وفي حالة عدم وجود لجنة يكون التصرف في الغرامات بموافقة الوزارة".'),
('boe26-929c08a3c9e8b23617fcbbc3','cmpzcv89s0aomvtrkbb6sf2jp','إذا لم يراع الطرف الذي أنهى العقد غير المحدد المدة المهلة المحدد للإشعار وفقاً للمادة (الخامسة والسبعين) من هذا النظام، فإنه يلتزم بأن يدفع للطرف الآخر عن مهلة الإشعار مبلغاً مساوياً لأجر العامل عن المهلة نفسها، ما لم يتفق الطرفان على أكثر من ذلك','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"إذا لم يراع الطرف الذي أنهى العقد غير المحدد المدة المهلة المحدد للإشعار وفقاً للمادة (الخامسة والسبعين) من هذا النظام، فإنه يلتزم بأن يدفع للطرف الآخر عن مهلة الإشعار مبلغاً مساوياً لأجر العامل عن المهلة نفسها، ما لم يتفق الطرفان على أكثر من ذلك".'),
('boe26-06763bf30f315510f0bb957c','cmpzcv89s0aoqvtrkvtuetnbq','لا يجوز لصاحب العمل فسخ العقد دون مكافأة العامل، أو إشعاره، أو تعويضه؛ إلا في الحالات الآتية، وبشرط أن يتيح له الفرصة لكي يبدي أسباب معارضته للفسخ :

1 - إذا وقع من العامل اعتداء على صاحب العمل أو المدير المسؤول أو أحد رؤسائه أو مرؤوسيه أثناء العمل أو بسببه.

2 - إذا لم يؤدِّ العامل التزاماته الجوهرية المترتبة على عقد العمل أو لم يطع الأوامر المشروعة أو لم يراعِ عمداً التعليمات – التي أعلن عنها صاحب العمل في مكان ظاهر – الخاصة بسلامة العمل والعمال رغم إنذاره كتابة.

3 - إذا ثبت اتباع العامل سلوكاً سيئاً، أو ارتكابه عملاً مخلاً بالشرف أو الأمانة.

4 - إذا وقع من العامل - عمداً - أيُّ فعلٍ أو تقصيرٍ يقصد به إلحاق خسارة مادية بصاحب العمل، بشرط أن يبلغ صاحب العمل الجهات المختصة بالحادث خلال أربع وعشرين ساعة من وقت علمه بوقوعه.

5 - إذا ثبت أن العامل لجأ إلى التزوير ليحصل على العمل.

6 - إذا كان العامل مُعيَّناً تحت الاختبار.

7 - إذا تغيب العامل دون سبب مشروع أكثر من ثلاثين يوماً خلال السنة العقدية الواحدة أو أكثر من خمسة عشر يوماً متتالية، على أن يسبق الفصل إنذار كتابي من صاحب العمل للعامل بعد غيابه عشرين يوماً في الحالة الأولى وانقطاعه عشرة أيام في الحالة الثانية.

8 - إذا ثبت أن العامل استغل مركزه الوظيفي بطريقة غير مشروعة للحصول على نتائج ومكاسب شخصية.

9 - إذا ثبت أن العامل أفشى الأسرار الصناعية أو التجارية الخاصة بالعمل الذي يعمل فيه','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"لا يجوز لصاحب العمل فسخ العقد دون مكافأة العامل، أو إشعاره، أو تعويضه؛ إلا في الحالات الآتية، وبشرط أن يتيح له الفرصة لكي يبدي أسباب معارضته للفسخ :

1 - إذا وقع من العامل اعتداء على صاحب العمل أو المدير المسؤول أو أحد رؤسائه أو مرؤوسيه أثناء العمل أو بسببه.

2 - إذا لم يؤدِّ العامل التزاماته الجوهرية المترتبة على عقد العمل أو لم يطع الأوامر المشروعة أو لم يراعِ عمداً التعليمات – التي أعلن عنها صا'),
('boe26-f33c27fe28db10547a851486','cmpzcv89s0aotvtrk4bfqr1i6','1 - إذا كان العمل المنوط بالعامل يسمح له بمعرفة عملاء صاحب العمل، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بمنافسته، ويجب لصحة هذا الشرط أن يكون مُحرراً ومُحدداً، من حيث الزمان والمكان ونوع العمل، ويجب ألا تزيد مدته على سنتين من تاريخ انتهاء العلاقة بين الطرفين.

2 - إذا كان العمل المنوط بالعامل يسمح له بالاطلاع على أسرار عمله، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بإفشاء أسراره، ويجب لصحة هذا الشرط أن يكون محرراً ومحدداً، من حيث الزمان والمكان ونوع العمل.

3 - استثناء من أحكام هذا النظام، لصاحب العمل رفع دعوى خلال سنة من تاريخ اكتشاف مخالفة العامل لأيٍّ من التزاماته الواردة في هذه المادة','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - إذا كان العمل المنوط بالعامل يسمح له بمعرفة عملاء صاحب العمل، جاز لصاحب العمل – حمايةً لمصالحه المشروعة – أن يشترط على العامل ألا يقوم بعد انتهاء العقد بمنافسته، ويجب لصحة هذا الشرط أن يكون مُحرراً ومُحدداً، من حيث الزمان والمكان ونوع العمل، ويجب ألا تزيد مدته على سنتين من تاريخ انتهاء العلاقة بين الطرفين.

2 - إذا كان العمل المنوط بالعامل يسمح له بالاطلاع على أسرار عمله، جاز لصاحب العمل – حما'),
('boe26-4dbb867ac14dee4125df2ba6','cmpzcv89s0ap0vtrkf1uyewpp','1 - يجب دفع أجر العامل وكل مبلغ مستحق له بالعملة الرسمية للبلاد طبقاً للأحكام الآتية :

أ - العمال باليومية : تصرف أجورهم مرة كل أسبوع على الأقل.

ب - العمال ذوو الأجور الشهرية : تصرف أجورهم مرة في الشهر.

ج - إذا كان العمل يؤدى بالقطعة، ويحتاج لمدة تزيد على أسبوعين، فيجب أن يحصل العامل على دفعة كل أسبوع تتناسب مع ما أتمه من العمل، ويصرف باقي الأجر كاملاً خلال الأسبوع التالي لتسليم العمل.

د - في غير ما ذكر، تؤدى إلى العمال أجورهم مرة كل أسبوع على الأقل.

2 - تلزم المنشآت بدفع الأجور في حسابات العمال عن طريق البنوك المعتمدة في المملكة، بشرط ألا يتجاوز موعد استحقاقها المواعيد المحددة أعلاه، ويجوز للوزير استثناء بعض المنشآت من ذلك','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - يجب دفع أجر العامل وكل مبلغ مستحق له بالعملة الرسمية للبلاد طبقاً للأحكام الآتية :

أ - العمال باليومية : تصرف أجورهم مرة كل أسبوع على الأقل.

ب - العمال ذوو الأجور الشهرية : تصرف أجورهم مرة في الشهر.

ج - إذا كان العمل يؤدى بالقطعة، ويحتاج لمدة تزيد على أسبوعين، فيجب أن يحصل العامل على دفعة كل أسبوع تتناسب مع ما أتمه من العمل، ويصرف باقي الأجر كاملاً خلال الأسبوع التالي لتسليم العمل.

د - في '),
('boe26-a371c0ae6e1a0211e5f966a8','cmpzcv89s0appvtrkcgzx2hvd','1 - للعامل - إذا وافق صاحب العمل على انتسابه إلى مؤسسة تعليمية أو قَبِل استمراره فيها – الحق في إجازة بأجر كامل لتأدية الامتحان عن سنة غير معادة تحدد مدتها بعد أيام الامتحان الفعلية. أما إذا كان الامتحان عن سنة معادة فيكون للعامل الحق في إجازة دون أجر بعدد أيام الامتحان الفعلية. ويحرم العامل من أجر الإجازة إذا ثبت أنه لم يؤدِّ الامتحان، مع عدم الإخلال بحق صاحب العمل في مساءلته تأديبيًّا.

2 - إذا لم يحصل العامل على موافقة صاحب العمل على انتسابه إلى مؤسسة تعليمية، فله أن يحصل على إجازة لتأدية الامتحان بعدد أيام الامتحان الفعلية تحتسب من إجازته السنوية في حال توافرها، وعند تعذر ذلك فللعامل أن يحصل على إجازة دون أجر بعدد أيام الامتحان الفعلية.

3 - على العامل أن يتقدم بطلب الإجازة قبل موعدها بخمسة عشر يوماً على الأقل.

4 - لصاحب العمل أن يطلب من العامل تقديم الوثائق المؤيدة لطلب الإجازة، وكذلك ما يدل على أدائه الامتحان','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"1 - للعامل - إذا وافق صاحب العمل على انتسابه إلى مؤسسة تعليمية أو قَبِل استمراره فيها – الحق في إجازة بأجر كامل لتأدية الامتحان عن سنة غير معادة تحدد مدتها بعد أيام الامتحان الفعلية. أما إذا كان الامتحان عن سنة معادة فيكون للعامل الحق في إجازة دون أجر بعدد أيام الامتحان الفعلية. ويحرم العامل من أجر الإجازة إذا ثبت أنه لم يؤدِّ الامتحان، مع عدم الإخلال بحق صاحب العمل في مساءلته تأديبيًّا.

2 - إذا '),
('boe26-0de17112fc60bc1220a3f1b2','cmpzcv89s0aqbvtrkr1h6a1t2','للمصاب - في حالة عجزه المؤقت عن العمل الناتج من إصابة عمل - الحق في معونة مالية تعادل أجره كاملاً لمدة ستين يوماً ثم يستحق مقابلاً ماليًّا يعادل (75%) من أجره طوال المدة التي يستغرقها علاجه. فإذا بلغت مدة العلاج سنة أو تقرر طبيًّا عدم احتمال شفائه وحالته الصحية لا تمكنه من العمل، عُدت الإصابة عجزاً كليًّا، وينهي العقد ويعوض عن الإصابة. ولا يكون لصاحب العمل حق في استرداد ما دفعه إلى المصاب خلال تلك السنة','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"للمصاب - في حالة عجزه المؤقت عن العمل الناتج من إصابة عمل - الحق في معونة مالية تعادل أجره كاملاً لمدة ستين يوماً ثم يستحق مقابلاً ماليًّا يعادل (75%) من أجره طوال المدة التي يستغرقها علاجه. فإذا بلغت مدة العلاج سنة أو تقرر طبيًّا عدم احتمال شفائه وحالته الصحية لا تمكنه من العمل، عُدت الإصابة عجزاً كليًّا، وينهي العقد ويعوض عن الإصابة. ولا يكون لصاحب العمل حق في استرداد ما دفعه إلى المصاب خلال تلك'),
('boe26-8562394e65c2766dc3e77bbb','cmpzcv89t0aqtvtrkim954vnt','لا يجوز لصاحب العمل فصل العاملة أو إنذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع، ويشمل ذلك مدة مرضها الناشئ عن أي منهما، على أن يثبت المرض بشهادة طبية معتمدة، وأن لا تتجاوز مدة غيابها (مائة وثمانين) يوماً في السنة سواءً أكانت متصلة أم متفرقة','2019-07-30','مرسوم ملكي رقم م/134 وتاريخ 27/11/1440هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','عُدلت هذه المادة بموجب المرسوم الملكي رقم (م / 134) وتاريخ 27 / 11 / 1440هـ،  لتكون بالنص الآتي: "لا يجوز لصاحب العمل فصل العاملة أو إنذارها بالفصل أثناء حملها أو تمتعها بإجازة الوضع، ويشمل ذلك مدة مرضها الناشئ عن أي منهما، على أن يثبت المرض بشهادة طبية معتمدة، وأن لا تتجاوز مدة غيابها (مائة وثمانين) يوماً في السنة سواءً أكانت متصلة أم متفرقة".'),
('boe26-68375ef1160ead97edeebee4','cmpzcv89t0aqyvtrkqlm8ob4q','1 - للمرأة العاملة المسلمة التي يتوفى زوجها الحق في إجازة عدة بأجر كامل لمدة لا تقل عن أربعة أشهر وعشرة أيام من تاريخ الوفاة، ولها الحق في تمديد هذه الإجازة دون أجر إن كانت حاملاً - خلال هذه الفترة - حتى تضع حملها، ولا يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها – بموجب هذا النظام – بعد وضع حملها.

2 - للمرأة العاملة غير المسلمة التي يتوفى زوجها الحق في إجازة بأجر كامل لمدة خمسة عشر يوماً.

وفي جميع الأحوال لا يجوز للعاملة المتوفى عنها زوجها ممارسة أي عمل لدى الغير خلال هذه المدة.

ويحق لصاحب العمل أن يطلب الوثائق المؤيدة للحالات المشار إليها','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"1 - للمرأة العاملة المسلمة التي يتوفى زوجها الحق في إجازة عدة بأجر كامل لمدة لا تقل عن أربعة أشهر وعشرة أيام من تاريخ الوفاة، ولها الحق في تمديد هذه الإجازة دون أجر إن كانت حاملاً - خلال هذه الفترة - حتى تضع حملها، ولا يجوز لها الاستفادة من باقي إجازة العدة الممنوحة لها – بموجب هذا النظام – بعد وضع حملها.

2 - للمرأة العاملة غير المسلمة التي يتوفى زوجها الحق في إجازة بأجر كامل لمدة خمسة عشر يوماً'),
('boe26-12e492e92b12d4a56ca80c00','cmpzcv89t0arovtrki3o3z0m4','لا يجوز تشغيل أي شخص في المنجم أو المحجر لم يتم الثامنة عشرة من العمر','2020-08-26','مرسوم ملكي رقم م/5 وتاريخ 7/1/1442هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م / 5) وتاريخ 7 / 1 / 1442هـ، لتكون بالنص الآتي: "لا يجوز تشغيل أي شخص في المنجم أو المحجر لم يتم الثامنة عشرة من العمر".

 '),
('boe26-a989e0922bb025c07944debb','cmpzcv89t0arwvtrkhmxfm6ne','يتولى تفتيش العمل مفتشون من موظفي الوزارة، أو من غيرهم من السعوديين، يحددهم الوزير أو من يفوضه، وتكون لهم الصلاحيات والاختصاصات المنصوص عليها في هذا النظام','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي:

"يتولى تفتيش العمل مفتشون من موظفي الوزارة، أو من غيرهم من السعوديين، يحددهم الوزير أو من يفوضه، وتكون لهم الصلاحيات والاختصاصات المنصوص عليها في هذا النظام".'),
('boe26-a2316ce59dcd3da2dad6c77f','cmpzcv89t0arzvtrkz43ptsnn','يلتزم مفتشو العمل - قبل مباشرتهم لمهماتهم - بتوقيع تعهد وفق النموذج الذي تعده الوزارة، يتضمن التزامهم بأداء عملهم بكل أمانة وإخلاص، وألا يفشوا سرَّ أيِّ اختراعٍ صناعيٍّ، أو غير ذلك من الأسرار التي يطلعون عليها بحكم عملهم. ويحمل مفتش العمل بطاقة من الوزارة تثبت صفته','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"يلتزم مفتشو العمل - قبل مباشرتهم لمهماتهم - بتوقيع تعهد وفق النموذج الذي تعده الوزارة، يتضمن التزامهم بأداء عملهم بكل أمانة وإخلاص، وألا يفشوا سرَّ أيِّ اختراعٍ صناعيٍّ، أو غير ذلك من الأسرار التي يطلعون عليها بحكم عملهم. ويحمل مفتش العمل بطاقة من الوزارة تثبت صفته".'),
('boe26-549f853a357c3c8f7272ad79','cmpzcv89t0as5vtrki2x156eq','إذا تحقق للمفتش أثناء التفتيش وجود مخالفة لأحكام هذا النظام أو اللائحة أو القرارات الصادرة تنفيذاً له، فعليه تحرير محضر ضبط بالمخالفة وفقاً للأحكام الواردة في اللائحة التنفيذية لضبط أعمال التفتيش وتنظيمها، ورفعه إلى الوزير؛ لإصدار قرار بذلك','2015-03-25','مرسوم ملكي رقم م/46 وتاريخ 5/6/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/08381293-6388-48e2-8ad2-a9a700f2aa94/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/ 46) وتاريخ 5 / 6 / 1436 هـ ؛ لتكون بالنص الآتي :

"إذا تحقق للمفتش أثناء التفتيش وجود مخالفة لأحكام هذا النظام أو اللائحة أو القرارات الصادرة تنفيذاً له، فعليه تحرير محضر ضبط بالمخالفة وفقاً للأحكام الواردة في اللائحة التنفيذية لضبط أعمال التفتيش وتنظيمها، ورفعه إلى الوزير؛ لإصدار قرار بذلك".'),
('boe26-9ca55adf25d6682744a83e92','cmpz6qln10buxcwg2v2dtvt6t','يسوى المعاش على أساس جزء من خمسة وثلاثين جزءًا من الراتب الأساسي الأخير على أن لا يتجاوز المعاش مقدار هذا الراتب','1976-07-06','مرسوم ملكي رقم م/56 وتاريخ 9/7/1396هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','عدلت هذه المادة  بموجب المرسوم الملكي  رقم (م/56) وتاريخ 9 / 7 / 1396 هـ ، ليصبح نصها كمايلى :

" يسوى المعاش على أساس جزء من خمسة وثلاثين جزءًا من الراتب الأساسي الأخير على أن لا يتجاوز المعاش مقدار هذا الراتب".'),
('boe26-0f11bd779c34be1d710c5409','cmpz6qn7v0bvhcwg2ekkyysgo','( يسوى معاش من يصاب من العسكريين بعجز كلي بسبب العمليات الحربية أو بسبب الأسر أو نتيجة إصابته خلال خدمة أُمر بها أثناء مواجهة التنظيمات المسلحة المعادية أو أثناء إطلاق النار خلال اقتحام أماكن المخربين أو مطاردة المهربين على أساس راتب أعلى درجة في سلم الرواتب للرتبة التي تعلو رتبته مباشرة، أما إذا كانت الإصابة قد أحدثت عجزًا جزئيًّا أوجب فصله من الخدمة العسكري فيمنح أربعة أخماس هذا الراتب ) .','1987-06-15','مرسوم ملكي رقم م/50 وتاريخ 19/10/1407هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','عدلت هذه المادة  بالمرسوم الملكي    رقم (م/50) وتاريخ 19 / 10 / 1407 هـ ، لتصبح بالنص التالى :

( يسوى معاش من يصاب من العسكريين بعجز كلي بسبب العمليات الحربية أو بسبب الأسر أو نتيجة إصابته خلال خدمة أُمر بها أثناء مواجهة التنظيمات المسلحة المعادية أو أثناء إطلاق النار خلال اقتحام أماكن المخربين أو مطاردة المهربين على أساس راتب أعلى درجة في سلم الرواتب للرتبة التي تعلو رتبته مباشرة، أما إذا كانت الإصابة قد أحدثت عجزًا جزئيًّا أوجب فصله من الخدمة العسكري فيمنح أربعة أخماس هذا الراتب ) .'),
('boe26-311b37c139d0bde39699ae9a','cmpz6qo0c0bvrcwg2b2cfs4fe','المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك','2021-06-03','مرسوم ملكي رقم م/93 وتاريخ 1442/10/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/93) وتاريخ 1442/10/22هـ لتكون بالنص الآتي: " المستحقون عن صاحب المعاش هم: الزوج أو الزوجة، والأم والأب، والابن والبنت، وابن وبنت الابن الذي توفي في حياة صاحب المعاش، والأخ والأخت، والجد والجدة. وفيما عدا الزوجة والابن والبنت، فيشترط لاستحقاق الشخص أن يكون معتمداً في إعالته على صاحب المعاش عند وفاته. ويحدد مجلس إدارة المؤسسة العامة للتقاعد بقرار منه متى يعتبر الشخص معتمداً في إعالته على صاحب المعاش، وتاريخ بدء صرف الاستحقاق، وإجراءات إثبات ذلك".'),
('boe26-c87f9f3038bfa1935adc98cf','cmpz6qoyh0bw3cwg20iogdri8','إذا لم يعد العسكري متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادتين (9) و (10) من هذا النظام','2022-03-23','مرسوم ملكي رقم م/80 وتاريخ 1443/8/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0838afd4-ca76-4b4a-b1d1-a9a700f22afd/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/80) وتاريخ 1443/8/20هـ، لتكون بالنص الآتي: " إذا لم يعد العسكري متمتعاً بالجنسية العربية السعودية، يُمنح مكافأة تحسب وفق أحكام المادتين (9) و (10) من هذا النظام".'),
('boe26-fdbf3c3c93f3fced1b508cd6','cmpzcv6870a4kvtrkid7nmfjt','يعاقب بالسجن مدة لا تزيد على ستة أشهر وبغرامة لا تتجاوز تسعين ألف ريال أو بإحدى هاتين العقوبتين، كل من زاول صناعة المعادن الثمينة ومشغولاتها أو الأحجار الكريمة دون ترخيص','2021-09-02','مرسوم ملكي رقم م/13 وتاريخ 1443/1/25هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/0f54d227-1450-4231-93cd-a9a700f29821/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/13) وتاريخ 1443/1/25هـ، لتكون بالنص الآتي: " يعاقب بالسجن مدة لا تزيد على ستة أشهر وبغرامة لا تتجاوز تسعين ألف ريال أو بإحدى هاتين العقوبتين، كل من زاول صناعة المعادن الثمينة ومشغولاتها أو الأحجار الكريمة دون ترخيص".'),
('boe26-e285c14a7ae562582a3f2233','cmpz6qxzr0bz7cwg2d6shir9f','تكون قرارات المجلس نافذة بعد توقيعها من رئيس مجلس الخدمة العسكرية، وتستثنى منها القرارات التى تتطلب موضوعاتها استكمال إجراءات نظامية في شأنها، وتحيل الأمانة العامة لمجلس الخدمة العسكرية هذه القرارات إلى ديوان رئاسة مجلس الوزراء، لإكمال مايلزم في شأنها.','2011-03-08','مرسوم ملكي رقم م/21 وتاريخ 3/4/1432هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/11d3d5b0-dddf-443a-9851-a9a700f23208/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م / 21 ) وتاريخ 3 / 4 / 1432 هـ ، لتصبح بالنص التالى :

" تكون قرارات المجلس نافذة بعد توقيعها من رئيس مجلس الخدمة العسكرية، وتستثنى منها القرارات التى تتطلب موضوعاتها استكمال إجراءات نظامية في شأنها، وتحيل الأمانة العامة لمجلس الخدمة العسكرية هذه القرارات إلى ديوان رئاسة مجلس الوزراء، لإكمال مايلزم في شأنها."'),
('boe26-b706d659818a1919bead83e0','cmpz5uw0v011fcwg23hqhqxdo','(يجب أن يكون الإعلان منسجماً مع عادات وتقاليد البلاد، وأن تتلاءم مادته مع الذوق السليم، وأن تكون الصور والكتابات في إطار الآداب الإسلامية، مع التقيد بقواعد اللغة العربية الفصحى، وبما يصدر من الجهات ذات العلاقة فيما يخص الضوابط الشرعية للإعلانات) .','2001-01-22','قرار مجلس الوزراء رقم 242 وتاريخ 27/10/1421هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/16c49913-599f-406b-b016-a9a700f172c9/1','عدلت هذه المادة بموجب قرار مجلس الوزراء رقم (242) وتاريخ 27/ 10/ 1421هـ ،لتصبح بالنص الآتى:

(يجب أن يكون الإعلان منسجماً مع عادات وتقاليد البلاد، وأن تتلاءم مادته مع الذوق السليم، وأن تكون الصور والكتابات في إطار الآداب الإسلامية، مع التقيد بقواعد اللغة العربية الفصحى، وبما يصدر من الجهات ذات العلاقة فيما يخص الضوابط الشرعية للإعلانات) .'),
('boe26-4d0dcdfd40af158c4ad56993','cmpzcv9t60b3mvtrkbmjwfqub','ينشأ بموجب التنظيم مجلس يسمى مجلس شؤون الأسرة يرتبط تنظيمياً بمجلس الشؤون الاقتصادية والتنمية، وبرئاسة معالي وزير الموارد البشرية والتنمية الاجتماعية، ويتمتع بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقره في مدينة الرياض، وله إنشاء فروع أو مكاتب داخل المملكة بحسب الحاجة','2022-03-15','قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: " ينشأ بموجب التنظيم مجلس يسمى مجلس شؤون الأسرة يرتبط تنظيمياً بمجلس الشؤون الاقتصادية والتنمية، وبرئاسة معالي وزير الموارد البشرية والتنمية الاجتماعية، ويتمتع بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقره في مدينة الرياض، وله إنشاء فروع أو مكاتب داخل المملكة بحسب الحاجة".'),
('boe26-8dd10ce00b5bceb4ffd58d8c','cmpzcv9t60b3qvtrkifnvxi6n','يشكل المجلس ما يلزم من لجان فنية دائمة أو مؤقتة على أن يكون من بينها (لجنة الطفولة ولجنة كبار السن ولجنة المرأة) ويحدد المجلس أعضاء كل لجنة ومهماتها وآلية عملها وحوكمتها','2022-03-15','قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: "يشكل المجلس ما يلزم من لجان فنية دائمة أو مؤقتة على أن يكون من بينها (لجنة الطفولة ولجنة كبار السن ولجنة المرأة) ويحدد المجلس أعضاء كل لجنة ومهماتها وآلية عملها وحوكمتها".'),
('boe26-cd8781e8121978725b04c3b7','cmpzcv9t60b3rvtrk57771oul','يكون للمجلس أمانة عامة ترتبط بالرئيس، يرأسها أمين عام، يختاره الرئيس','2022-03-15','قرار مجلس الوزراء رقم 443 وتاريخ 1443/8/12هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1c026125-b0b2-4ea7-b374-a9a700f2c0ee/1','- عدلت هذه المادة بموجب قرار مجلس الوزراء رقم (443) وتاريخ 1443/8/12هـ، لتكون بالنص الآتي: "يكون للمجلس أمانة عامة ترتبط بالرئيس، يرأسها أمين عام، يختاره الرئيس".'),
('boe26-3aec25624b2806827518ddcf','cmpz9encb0cfnybvvqfwup3hk','أ - يكون تشكيل مجلس الخدمة المدنية من:

-  رئيس مجلس الوزراء         رئيساً

-   نائب رئيس مجلس الوزراء         نائباً للرئيس

-  رئيس الديوان العام للخدمة المدنية    عضواً

- أربعة من الوزراء أعضاء يعينون بأمر ملكي لمدة ثلاث سنوات.

- ثلاثة أعضاء من ذوي الاختصاص يعينون بأمر ملكي     لمدة ثلاث سنوات.

ب - تعقد جلسات المجلس الخدمة المدنية برئاسة رئيسه ، أو نائبه ، أو من يفوضه من بين أعضائه.','1982-09-04','مرسوم ملكي رقم م/53 وتاريخ 16/11/1402هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/1fe7fe77-d349-4fae-a561-a9a700f23a89/1','عدلت هذه المادة  بالمرسوم الملكي رقم (م / 53) وتاريخ 16 /11 /1402هـ ، لتصبح كالتالى :

أ - يكون تشكيل مجلس الخدمة المدنية من:

-  رئيس مجلس الوزراء         رئيساً

-   نائب رئيس مجلس الوزراء         نائباً للرئيس

-  رئيس الديوان العام للخدمة المدنية    عضواً

- أربعة من الوزراء أعضاء يعينون بأمر ملكي لمدة ثلاث سنوات.

- ثلاثة أعضاء من ذوي الاختصاص يعينون بأمر ملكي     لمدة ثلاث سنوات.

ب - تعقد جلسات المجلس الخدمة المدنية برئاسة رئيسه ، أو نائبه ، أو من يفوضه من بين أعضائه.'),
('boe26-100ca1a1a41b47da7b77ebe0','cmpz6h3dy08hzcwg21vue35d1','1- تودع جميع إيرادات الهيئة في حساب جاري وزارة المالية في البنك المركزي السعودي.

2- تفتح الهيئة حساباً لها في البنك المركزي السعودي، وتصرف منه وفق ميزانيتها المعتمدة، ولها فتح حسابات أخرى في البنوك المرخص لها بالعمل في المملكة','2022-12-27','قرار مجلس الوزراء رقم 376 وتاريخ 1444/6/3هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/216a2b6e-911e-4223-a11b-adab00c670a1/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (376) وتاريخ 1444/6/3هـ، لتكون بالنص الآتي:

" 1- تودع جميع إيرادات الهيئة في حساب جاري وزارة المالية في البنك المركزي السعودي.

2- تفتح الهيئة حساباً لها في البنك المركزي السعودي، وتصرف منه وفق ميزانيتها المعتمدة، ولها فتح حسابات أخرى في البنوك المرخص لها بالعمل في المملكة ".'),
('boe26-ea36da8422c2050f46c87775','cmpzcvci60bxuvtrktid7c47o','المؤسسة العامة للخطوط الجوية العربية السعودية مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية وترتبط تنظيميًا برئيس مجلس الوزراء، ويكون مقرها في محافظة جدة، ويجوز لمجلس الوزراء أن يقرر نقل مقرها إلى مكان آخر داخل المملكة','2012-01-09','قرار مجلس الوزراء رقم 28 وتاريخ 15/2/1433هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','تم تعديل هذه المادة بموجب قرار مجلس الوزراء رقم (28) وتاريخ 15 / 2 / 1433هـ ، لتصبح بالنص التالى :

"المؤسسة العامة للخطوط الجوية العربية السعودية مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية وترتبط تنظيميًا برئيس مجلس الوزراء، ويكون مقرها في محافظة جدة، ويجوز لمجلس الوزراء أن يقرر نقل مقرها إلى مكان آخر داخل المملكة".'),
('boe26-6873d7e23ab2a2a8abe16dd0','cmpzcvci60bxxvtrkwf71rnst','يتولى إدارة المؤسسة مجلس يرأسه سمو   وزير الدفاع والطيران     أو من ينيبه، وتسعة أعضاء يصدر بتسميتهم قرار من   مجلس الوزراء    ، بناء على ترشيح   وزير الدفاع والطيران  ، ممن تتوفر فيهم المؤهلات المناسبة، ويكون من بينهم:
1 -   مساعد وزير الدفاع والطيران لشؤون الطيران المدني  ،   ومدير عام المؤسسة ،   ورئيس الطيران المدني .
2 - ممثلون عن الجهات الحكومية ذات العلاقة.
3 - من يرشحهم   وزير الدفاع والطيران     من غير هؤلاء.
ويحدد قرار  مجلس الوزراء    فترة عضوية من يختارهم، ومقدار المكافأة التي تمنح مقابل عضوية المجلس .','1980-01-23','مرسوم ملكي رقم م/2 وتاريخ 5/3/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/2) وتاريخ 5 / 3 / 1400 هـ ، لتصبح بالنص التالى :

يتولى إدارة المؤسسة مجلس يرأسه سمو   وزير الدفاع والطيران     أو من ينيبه، وتسعة أعضاء يصدر بتسميتهم قرار من   مجلس الوزراء    ، بناء على ترشيح   وزير الدفاع والطيران  ، ممن تتوفر فيهم المؤهلات المناسبة، ويكون من بينهم:
1 -   مساعد وزير الدفاع والطيران لشؤون الطيران المدني  ،   ومدير عام المؤسسة ،   ورئيس الطيران المدني .
2 - ممثلون عن الجهات الحكومية ذات العلاقة.
3 - من يرشحهم   وزير الدفاع والطيران  '),
('boe26-a9e5ba0c1a8e66aca90ea441','cmpzcvci60bxzvtrkplxgeh7r','ينعقد مجلس إدارة المؤسسة في مقر المؤسسة أو في مدينة يحددها بدعوة من رئيسه، ويجب ألا تقل الجلسات التي يعقدها المجلس عن عشر جلسات في السنة.
ولا يكون انعقاد المجلس صحيحا إلا إذا حضره ستة أعضاء على الأقل بما فيهم الرئيس .','1980-01-23','مرسوم ملكي رقم م/2 وتاريخ 5/3/1400هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/2) وتاريخ 5 / 3 / 1400 هـ ، ليصبح نصها كالتالى :

"ينعقد مجلس إدارة المؤسسة في مقر المؤسسة أو في مدينة يحددها بدعوة من رئيسه، ويجب ألا تقل الجلسات التي يعقدها المجلس عن عشر جلسات في السنة.
ولا يكون انعقاد المجلس صحيحا إلا إذا حضره ستة أعضاء على الأقل بما فيهم الرئيس ."'),
('boe26-d130802f36b42d3feb26e7d0','cmpzcvci60by5vtrkmjlgc471','تعفى المؤسسة من أداء جميع الرسوم والطوابع وضرائب الدخل عن النشاط الاقتصادي الذي تمارسه في حدود الأغراض المنصوص عليها في المادة (الثانية) من هذا النظام، ويشمل هذا الإعفاء رسوم وقود الطائرات دون أنواع الوقود الأخرى الذي تستهلكه المؤسسة.','2005-08-16','مرسوم ملكي رقم م/42 وتاريخ 11/7/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/21bbfc47-571d-4916-82b6-a9a700f2e06c/1','عدلت هذه المادة  بموجب المرسوم الملكي رقم (م/42) وتاريخ 11 / 7 / 1426 هـ،  لتصبح بالنص التالى :

"تعفى المؤسسة من أداء جميع الرسوم والطوابع وضرائب الدخل عن النشاط الاقتصادي الذي تمارسه في حدود الأغراض المنصوص عليها في المادة (الثانية) من هذا النظام، ويشمل هذا الإعفاء رسوم وقود الطائرات دون أنواع الوقود الأخرى الذي تستهلكه المؤسسة."'),
('boe26-29d909db3065de0946301d9f','cmpzcuyse082avtrkbm6cgx2l','1- على الجهات ذات العلاقة وضع برامج صحية وتربوية وتعليمية ونفسية واجتماعية، لإعادة تأهيل الطفل الذي تعرض لإحدى حالات الإيذاء أو الإهمال.

2- تتولى وزارة الموارد البشرية والتنمية الاجتماعية - عند الحاجة - التنسيق مع  وزارة الصحة، لإخضاع مرتكب الإيذاء أو الإهمال لعلاج نفسي أو برامج تأهيلية بما يلائم حالته','2022-03-09','مرسوم ملكي رقم م/72 وتاريخ 1443/8/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/2d3cb83a-0379-4cde-8e0b-a9a700f272bd/1','- عدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/72) وتاريخ 1443/8/6هـ، لتكون بالنص الآتي:

"1- على الجهات ذات العلاقة وضع برامج صحية وتربوية وتعليمية ونفسية واجتماعية، لإعادة تأهيل الطفل الذي تعرض لإحدى حالات الإيذاء أو الإهمال.

2- تتولى وزارة الموارد البشرية والتنمية الاجتماعية - عند الحاجة - التنسيق مع  وزارة الصحة، لإخضاع مرتكب الإيذاء أو الإهمال لعلاج نفسي أو برامج تأهيلية بما يلائم حالته".'),
('boe26-103736b6007d8ed83b5ba9f6','cmpz9egl90cd9ybvvh2qx1zmq','يكون شغل وظائف المرتبتين (الرابعة عشرة) و(الخامسة عشرة) بقرار من مجلس الوزراء، ويكون شغل وظائف المرتبة (الثالثة عشرة) فما دون بقرار من الوزير المختص وفقاً للشروط والضوابط والإجراءات المحددة لهذه الوظائف، واستثناءً من ذلك؛ يجوز نقل من يشغل المرتبة (الرابعة عشرة) أو المرتبة (الخامسة عشرة) داخل الجهة بقرار من الوزير المختص، بعد أخذ موافقة رئيس مجلس الوزراء','2017-02-21','مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"يكون شغل وظائف المرتبتين (الرابعة عشرة) و(الخامسة عشرة) بقرار من مجلس الوزراء، ويكون شغل وظائف المرتبة (الثالثة عشرة) فما دون بقرار من الوزير المختص وفقاً للشروط والضوابط والإجراءات المحددة لهذه الوظائف، واستثناءً من ذلك؛ يجوز نقل من يشغل المرتبة (الرابعة عشرة) أو المرتبة (الخامسة عشرة) داخل الجهة بقرار من الوزير المختص، بعد أخذ موافقة رئيس مجلس الوزراء".'),
('boe26-4a5b78f9bbbc9c00a83a2135','cmpz9egqs0cdbybvvkzwo534z','تعلن وزارة الخدمة المدنية عن الوظائف التي في المرتبة (العاشرة) فما دون وما يعادلها في سلالم رواتب الخدمة المدنية، ويخضع جميع المتقدمين لشغل هذه الوظائف لتقويم تحدد وزارة الخدمة المدنية مقاييسه وإجراءاته في ضوء متطلبات الوظائف، ويجوز بعد اتفاق وزير الخدمة المدنية والوزير المختص؛ أن تعلن الجهة الإدارية عن الوظائف التي يتفق في شأنها وفق المقاييس والإجراءات التي تحددها وزارة الخدمة المدنية','2017-02-21','مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"تعلن وزارة الخدمة المدنية عن الوظائف التي في المرتبة (العاشرة) فما دون وما يعادلها في سلالم رواتب الخدمة المدنية، ويخضع جميع المتقدمين لشغل هذه الوظائف لتقويم تحدد وزارة الخدمة المدنية مقاييسه وإجراءاته في ضوء متطلبات الوظائف، ويجوز بعد اتفاق وزير الخدمة المدنية والوزير المختص؛ أن تعلن الجهة الإدارية عن الوظائف التي يتفق في شأنها وفق المقاييس والإجراءات التي تحددها وزارة الخدمة المدنية".  '),
('boe26-304cbdb61c7ce77d1fc09813','cmpz9ehte0cdpybvv9ludn9f3','لا يجوز للموظف الجمع بين وظيفته وممارسة مهنة أخرى، على أنه يجوز وفق لائحة يصدرها مجلس الوزراء السماح بالاشتغال بالمهن الحرة لمن تقضي المصلحة العامة السماح لهم بذلك؛ للحاجة إلى مهنهم','2017-02-21','مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 57) بتاريخ 24/ 5/ 1438هـ، لتكون بالنص الآتي:

"لا يجوز للموظف الجمع بين وظيفته وممارسة مهنة أخرى، على أنه يجوز وفق لائحة يصدرها مجلس الوزراء السماح بالاشتغال بالمهن الحرة لمن تقضي المصلحة العامة السماح لهم بذلك؛ للحاجة إلى مهنهم".'),
('boe26-a3c285ec98da036bf55b1999','cmpz9eil10cdzybvv7nbg1qr5','أ - يمنح الموظف المعين راتب أول درجة في مرتبة الوظيفة التي عين عليها، فإذا كان راتبه عند التعيين يساوي راتب هذه الدرجة أو يزيد عليه؛ يمنح راتب أول درجة تتجاوز راتبه عند التعيين.

ويجوز التعيين في غير الدرجة الأولى بالنسبة لمن يتوفر لديه مؤهلات معينة يحددها مجلس الوزراء.

ب - يمنح الموظف المرقى راتب أول درجة في مرتبة الوظيفة التي يرقى إليها، فإن كان راتبه عند الترقية يساوي راتب هذه الدرجة أو يزيد عليه؛ فيمنح راتب أول درجة تتجاوز راتبه، على ألا تقل الزيادة التي يحصل عليها المرقى في راتبه عن مقدار العلاوة المحددة للمرتبة التي كان مثبتاً عليها قبل الترقية على المرتبة الأعلى.

ج - إذا أعيد الموظف الذي ترك الخدمة إلى وظيفة في المرتبة نفسها التي كان يشغلها عند انتهاء خدمته؛ فيوضع في الدرجة نفسها التي كان عليها، أما إذا أعيد إلى وظيفة ذات مرتبة أعلى أو أدنى فيمنح راتب أول درجة يتجاوز راتبها راتب الدرجة التي كان يشغلها في السلم المطبق عليه، فإن كان راتبه يزيد على راتب آخر درجة في مرتبة الوظيفة؛ فيمنح هذه الدرجة','2017-02-21','مرسوم ملكي رقم م/57 وتاريخ 24/5/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/32f651e6-2976-439c-b418-a9a700f23fb2/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/57) بتاريخ 24/  5/ 1438هـ، لتكون بالنص الآتي:

"أ - يمنح الموظف المعين راتب أول درجة في مرتبة الوظيفة التي عين عليها، فإذا كان راتبه عند التعيين يساوي راتب هذه الدرجة أو يزيد عليه؛ يمنح راتب أول درجة تتجاوز راتبه عند التعيين.

ويجوز التعيين في غير الدرجة الأولى بالنسبة لمن يتوفر لديه مؤهلات معينة يحددها مجلس الوزراء.

ب - يمنح الموظف المرقى راتب أول درجة في مرتبة الوظيفة التي يرقى إليها، فإن كان راتبه عند الترقية يساوي راتب هذه الدرجة أو يزيد عليه؛'),
('boe26-5253d8221fb9fc5611c10d1b','cmpzcvd6a0c4hvtrk21l17lu3','( المادة السابعة بعد المائة: المركز الوطني لسلامة النقل (المركز) واختصاصه)

يتولى المركز التحقيق في الحوادث والوقائع التي تقع للطائرات المدنية في إقليم المملكة وللطائرات السعودية وللطائرات التي يشغلها أشخاص يحملون الجنسية السعودية فوق أعالي البحار أو فوق الأراضي غير المملوكة لإحدى الدول وفقاً للشروط والضوابط التي تحددها لائحة التحقيق. وللمركز في سبيل ذلك القيام بما يأتي:

أ- وضع لائحة التحقيق واعتمادها من مجلس إدارة المركز.

ب- تشكيل لجان التحقيق وتحديد صلاحياتها وتحديد القواعد الواجب مراعاتها، لإجراء التحقيق في هذه الحوادث والوقائع.

ج- إعداد تقرير عن الحالات والظروف المتعلق بكل حادث طيران يتم التحقيق فيه، وبيان أسبابه ونتائجه، وأي إجراءات أو قواعد يوصي بها لمنع تكرار مثل هذا الحادث مستقبلاً.

د- إصدار التعليمات والقواعد الواجب مراعاتها، لضمان تأمين سلامة الطيران وتلافي وقوع حوادث الطيران مستقبلاً.

هـ- نشر نتائج التحقيق في حوداث الطيران بعد اعتمادها من مجلس إدارة المركز.

يجوز للمركز في المملكة -بناءً على طلب السلطات المختصة في إحدى الدول الأجنبية التي يقع في إقليمها حادث طيران لطائرة مدنية سعودية، أو لطائرة يشغلها شخص يحمل الجنسية السعودية- أن يقوم بإجراء التحقيق الفني في الحادث، أو أن يشترك فيه.

يجوز للمركز إجراء التحقيق في حوادث الطيران التي تقع لأي طائرة مدنية في إقليم دولة أخرى بناء على طلب السلطات المختصة في هذه الدولة، وذلك بشرط أن تتحمل تلك الدولة جميع التكاليف والنفقات اللازمة والمترتبة على إجراء هذا التحقيق','2023-09-05','قرار مجلس الوزراء رقم 158 وتاريخ 1445/2/20هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/33ef05e2-f53e-4340-b5cb-a9a700f2ead1/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (158) وتاريخ 1445/2/20هـ، لتكون على النحو الآتي:

"( المادة السابعة بعد المائة: المركز الوطني لسلامة النقل (المركز) واختصاصه)

يتولى المركز التحقيق في الحوادث والوقائع التي تقع للطائرات المدنية في إقليم المملكة وللطائرات السعودية وللطائرات التي يشغلها أشخاص يحملون الجنسية السعودية فوق أعالي البحار أو فوق الأراضي غير المملوكة لإحدى الدول وفقاً للشروط والضوابط التي تحددها لائحة التحقيق. وللمركز في سبيل ذلك القيام بما يأتي:

أ- وضع لائحة التحقيق و'),
('boe26-4404a78c5780e13d07081555','cmpzcut6d06i0vtrkmtc03ant','المؤسسة العامة لتحلية المياه المالحة ، مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية ، ولها جميع الحقوق اللازمة لممارسة نشاطها ، وتتبع إداريا وزير المياه والكهرباء ، ومقرها الرئيس في مدينة الرياض ، ولها أن تنشئ فروعا أو مكاتب في المناطق أو المدن التي يقررها مجلس الإدارة .','2005-04-06','مرسوم ملكي رقم م/10 وتاريخ 27/2/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/37f95015-f360-45be-8f91-a9a700f244c1/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/10) وتاريخ 27 / 2 / 1426 هـ ، لتصبح بالنص الآتى :

"المادة الأولى :

المؤسسة العامة لتحلية المياه المالحة ، مؤسسة عامة مستقلة تتمتع بالشخصية الاعتبارية ، ولها جميع الحقوق اللازمة لممارسة نشاطها ، وتتبع إداريا وزير المياه والكهرباء ، ومقرها الرئيس في مدينة الرياض ، ولها أن تنشئ فروعا أو مكاتب في المناطق أو المدن التي يقررها مجلس الإدارة ."'),
('boe26-f29429fe77a695f2e58a51e3','cmpzcut6d06i3vtrk9dd0hrsg','يكون للمؤسسة مجلس إدارة يشكل على النحو الآتي:

ـ وزير المياه والكهرباء رئيساً

- محافظ المؤسسة نائباً للرئيس

ـ وكيل وزارة المياه والكهرباء عضواً

ـ وكيل وزارة الشؤون البلدية والقروية عضواً

ـ وكيل وزارة المالية عضواً

ـ وكيل وزارة البترول والثروة المعدنية عضواً

ـ وكيل وزارة الاقتصاد والتخطيط عضواً

ـ عضوان من القطاع الأهلي من ذوي الكفاية والأهلية يعنيان بقرار مدة عضويتهما ثلاث سنوات قابلة للتجديد مرة واحدة','2005-04-06','مرسوم ملكي رقم م/10 وتاريخ 27/2/1426هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/37f95015-f360-45be-8f91-a9a700f244c1/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/10) وتاريخ 27 / 2 / 1426 هـ ، لتصبح بالنص الآتى :

يكون للمؤسسة مجلس إدارة يشكل على النحو الآتي:

ـ وزير المياه والكهرباء رئيساً

- محافظ المؤسسة نائباً للرئيس

ـ وكيل وزارة المياه والكهرباء عضواً

ـ وكيل وزارة الشؤون البلدية والقروية عضواً

ـ وكيل وزارة المالية عضواً

ـ وكيل وزارة البترول والثروة المعدنية عضواً

ـ وكيل وزارة الاقتصاد والتخطيط عضواً

ـ عضوان من القطاع الأهلي من ذوي الكفاية والأهلية يعنيان بقرار مدة عضويتهما ثلاث سنوات قابلة للتجديد مرة'),
('boe26-d06e2cbd567f483bee75e0df','cmpz64hh4047rcwg2v50hp81x','تُشترط موافقة البنك المركزي السعودي على ترشيح أعضاء مجالس إدارات شركات التأمين وشركات إعادة التأمين وشركات مزاولي الخدمات المساندة للتأمين، وأعضاء لجان المراجعة واللجان المنبثقة عن هذه المجالس، ومديري تلك الشركات، والوظائف العليا التي يحددها البنك المركزي السعودي. ويضع البنك المركزي السعودي الضوابط الخاصة بتعيينهم.','2021-08-31','مرسوم ملكي رقم م/12 وتاريخ 1443/1/23هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/12) وتاريخ 1443/1/23هـ، لتكون بالنص الآتي:

" تُشترط موافقة البنك المركزي السعودي على ترشيح أعضاء مجالس إدارات شركات التأمين وشركات إعادة التأمين وشركات مزاولي الخدمات المساندة للتأمين، وأعضاء لجان المراجعة واللجان المنبثقة عن هذه المجالس، ومديري تلك الشركات، والوظائف العليا التي يحددها البنك المركزي السعودي. ويضع البنك المركزي السعودي الضوابط الخاصة بتعيينهم."'),
('boe26-75c56adaf5da20973a3a66f5','cmpz64jwx048jcwg2hrvgnswh','1 - تشكل لجنة ابتدائية (أو أكثر) بقرار من مجلس الوزراء من عدد لا يقل عن ثلاثة أعضاء متفرغين – إن أمكن – من ذوي الاختصاص، يكون أحدهم على الأقل مستشارًا نظاميًا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد، وتتولى الفصل فيما يأتي:

أ – جميع المنازعات الناشئة عن عقود التأمين، بما فيها التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات وغيرها في حالة حلولها محل المؤمن له.

ب - المنازعات التي تقع بين شركات التأمين وشركات إعادة التأمين أو فيما بين كل منها، أو المنازعات التي تقع بين تلك الشركات ومزاولي المهن الحرة المتعلقة بنشاط التأمين.

ج - مخالفة التعليمات الرقابية والإشرافية لشركات التأمين وإعادة التأمين أو أي من هذين النشاطين.

د - مخالفات مزاولي المهن الحرة المشار إليها في المادة (الثامنة عشرة) من هذا النظام.

هـ - المخالفات الناشئة عن تطبيق هذا النظام، وإيقاع الغرامات المنصوص عليها في المادة (الحادية والعشرين) من هذا النظام.

2 - إذا كانت المخالفة تنطوي على جريمة، فعلى اللجنة إحالتها إلى جهة التحقيق المختصة للتحقيق مع المخالف تمهيدًا لإقامة الدعوى أمام المحكمة الجزائية المختصة، للنظر في توقيع العقوبات الواردة في هذا النظام أو أي نظام آخر بحسب الأحوال. على أنه إذا رأت جهة التحقيق المختصة أنه لا وجه لإقامة الدعوى في الشق الجنائي، فعليها إعادة الأوراق إلى اللجنة للنظر في المخالفة واتخاذ ما يلزم حيالها وفقًا لما ورد في هذا النظام','2013-04-08','مرسوم ملكي رقم م/30 وتاريخ 27/5/1434هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم ( م/30 ) وتاريخ 27 / 5 / 1434 هـ، لتكون بالنص الآتى :

"1 - تشكل لجنة ابتدائية (أو أكثر) بقرار من مجلس الوزراء من عدد لا يقل عن ثلاثة أعضاء متفرغين – إن أمكن – من ذوي الاختصاص، يكون أحدهم على الأقل مستشارًا نظاميًا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد، وتتولى الفصل فيما يأتي:

أ – جميع المنازعات الناشئة عن عقود التأمين، بما فيها التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات وغيرها في حالة حلولها محل ا'),
('boe26-af8f461dcc14413641c8cd84','cmpz64jwx048jcwg2hrvgnswh','تشكل بقرار من مجلس الوزراء لجنة ابتدائية (أو أكثر) من أعضاء من ذوي الاختصاص لا يقل عددهم عن ثلاثة، ويكونون متفرغين إن أمكن، ويكون أحدهم - على الأقل - مستشاراً نظاميًّا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد؛ تتولى ما يأتي:

الفصل في جميع المنازعات الناشئة عن عقود التأمين، بما فيهم التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات والغير في حالة حلولها محل المؤَّمن له، والمنازعات الناشئة بين مزاولي الخدمات المساندة للتأمين وعملائهم.

الفصل في جميع المنازعات التي تقع بين شركات التأمين وشركات إعادة التأمين ومزاولي الخدمات المساندة للتأمين.

النظر في تظلم ذوي الشأن من العقوبات والإجراءات الصادرة من البنك المركزي السعودي بحقهم وفق المادة (التاسعة عشرة) من هذا النظام، على أن يقدم التظلم إلى اللجنة خلال (ثلاثين) يوماً من تاريخ إبلاغ المركزي السعودي لهم بالإجراء. ويحق للجنة إصدار قرار بالتعويض أو إعادة الحال إلى ما كانت عليه أو إصدار أي قرار آخر تراه مناسباً ويضمن حق المتضرر.

النظر في قرارات إلغاء التراخيص التي تصدر من البنك المركزي السعودي.','2021-08-31','مرسوم ملكي رقم م/12 وتاريخ 1443/1/23هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3e3c6fc3-9a45-4a0e-b28e-a9a700f1ad14/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/12) وتاريخ 1443/1/23هـ، لتكون بالنص الآتي:

" تشكل بقرار من مجلس الوزراء لجنة ابتدائية (أو أكثر) من أعضاء من ذوي الاختصاص لا يقل عددهم عن ثلاثة، ويكونون متفرغين إن أمكن، ويكون أحدهم - على الأقل - مستشاراً نظاميًّا، وتكون مدة العضوية ثلاث سنوات قابلة للتجديد؛ تتولى ما يأتي:

الفصل في جميع المنازعات الناشئة عن عقود التأمين، بما فيهم التي تقع بين شركات التأمين وعملائها والمستفيدين من التغطيات التأمينية، أو بين هذه الشركات والغير في حالة حلولها محل'),
('boe26-9f949fdc2b683e22dfd42186','cmpz6ggv2089rcwg2spywcgmz','تتمتع الهيئة بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقرها الرئيس في مدينة الرياض، ولها أن تنشى فروعاً أو مكاتب تابعة لها داخل المملكة بحسب الحاجة','2025-10-14','قرار مجلس الوزراء رقم 283 وتاريخ 1447/4/22هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/3fd2d5d4-e39f-4543-a69f-ad0100b32c4d/1','- عُدلت هذه المادة وذلك  بموجب قرار مجلس الوزراء رقم (283) وتاريخ 1447/4/22هـ، لتصبح بالنص الآتي:

"تتمتع الهيئة بالشخصية الاعتبارية وبالاستقلال المالي والإداري، ويكون مقرها الرئيس في مدينة الرياض، ولها أن تنشى فروعاً أو مكاتب تابعة لها داخل المملكة بحسب الحاجة".'),
('boe26-975d742d70aee7d7eb38d39c','cmpzcvb5l0bjhvtrk3fkyerej','1 - تستوفى مبالغ الأجور والإيجارات المقررة بموجب هذا النظام، وتودع في حساب الهيئة في مؤسسة النقد العربي السعودي وفقاً للأنظمة المعمول بها في المملكة.
2 - في حالة تأخير سداد الأجور عن موعد الاستحقاق، رغم تكرار المطالبة بالسداد، وعدم وجود ضمان يستوفى منه مبلغ الأجر، يعد المتأخر عن السداد مماطلاً، وتستوفى منه غرامة تأخير لا تتجاوز (30%) ثلاثين في المائة من المبلغ المستحق، وتودع الغرامة في الخزينة العامة للدولة.
3 - على الهيئة تضمين العقد الذي تبرمه مع المستأجر نصاً يقضي بإلزامه بتقديم ضمان بنكي عند توقيع العقد بما يعادل ما نسبته (30%) ثلاثون في المائة من قيمته، كضمان لاستيفاء الإيجار المستحق عليه، ويكون هذا الضمان ساري المفعول وغير قابل للإلغاء إلا بعد انتهاء مدة العقد وبموافقة الهيئة، ويستوفى منه أيُّ مبلغ يُستحق على المستأجر فور استحقاقه وفق أحكام العقد، مع مطالبته بتغطية ما نقص من مبلغ الضمان فوراً','2017-07-11','مرسوم ملكي رقم م/105 وتاريخ 17/10/1438هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/456ab486-9c16-4c7b-993c-a9a700f2cc4a/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م/ 105) بتاريخ 17/ 10/ 1438هـ، لتكون بالنص الآتي:

"1 - تستوفى مبالغ الأجور والإيجارات المقررة بموجب هذا النظام، وتودع في حساب الهيئة في مؤسسة النقد العربي السعودي وفقاً للأنظمة المعمول بها في المملكة.
2 - في حالة تأخير سداد الأجور عن موعد الاستحقاق، رغم تكرار المطالبة بالسداد، وعدم وجود ضمان يستوفى منه مبلغ الأجر، يعد المتأخر عن السداد مماطلاً، وتستوفى منه غرامة تأخير لا تتجاوز (30%) ثلاثين في المائة من المبلغ المستحق، وتودع الغرامة في الخزينة العام'),
('boe26-3e8edcb4c676fbe3e6636cda','cmpzcvb5l0bjsvtrkqgks84p0','يقوم مجلس الإدارة باتخاذ الآتي:

1   -	مراجعة الأجور والإيجارات وفئاتها الواردة في هذا النظام، وتعديلها واعتمادها، متى اقتضت الحاجة ذلك، وعليه عند قيامه بذلك مراعاة الآتي:

أ‌ - أن تكون فئات الأجور والإيجارات ضمن المعايير المعمول بها وضمن الأسعار المنافسة دولياً وإقليمياً.

ب‌ - أن تكون الأجور والإيجارات محفزة لشركات الطيران الدولية والخاصة للتشغيل في مطارات المملكة واستخدام مرافقها والاستفادة من خدماتها.

ج - الأخذ في الاعتبار الأهمية الاستراتيجية لبعض المطارات من حيث ازدحامها أو تدني نسبة الحركة فيها، والتفريق – كلما كان ذلك مناسباً – بين أوقات الذروة خلال الموسم والأوقات الأخرى.

2 - استحداث فئات للخدمات التي تقدمها الهيئة، وتحديد مبالغ أجورها، وتعديلها، متى اقتضت الحاجة لذلك.

3 - 	اعتماد أجور خدمات المطارات والملاحة الجوية في حال تقديم القطاع الخاص لها','2015-04-28','مرسوم ملكي رقم م/53 وتاريخ 9/7/1436هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/456ab486-9c16-4c7b-993c-a9a700f2cc4a/1','تم تعديل هذه المادة بموجب المرسوم الملكي رقم (م / 53) وتاريخ 9 / 7 / 1436هـ،  لتصبح بالنص الآتي:

"يقوم مجلس الإدارة باتخاذ الآتي:

1   -	مراجعة الأجور والإيجارات وفئاتها الواردة في هذا النظام، وتعديلها واعتمادها، متى اقتضت الحاجة ذلك، وعليه عند قيامه بذلك مراعاة الآتي:

أ‌ - أن تكون فئات الأجور والإيجارات ضمن المعايير المعمول بها وضمن الأسعار المنافسة دولياً وإقليمياً.

ب‌ - أن تكون الأجور والإيجارات محفزة لشركات الطيران الدولية والخاصة للتشغيل في مطارات المملكة واستخدام مرافقها والاستفادة من خ'),
('boe26-0ecee60b4df420720f91bad2','cmpz65k2004kjcwg2fopadkq8','مع مراعاة ما تقتضي به الأنظمة الأخرى، يعاقب بالحبس مدة لا تزيد على ثلاث سنوات وبغرامة لا تزيد على خمسين ألف ريال أو بإحدى هاتين العقوبتين كل من أقدم بسوء نية على ارتكاب أحد الأفعال الآتية:

أ - إذا سحب شيكا لا يكون له مقابل وفاء قائم وقابل للسحب أو يكون له مقابل وفاء أقل من قيمة الشيك.

ب - إذا استرد بعد إعطاء الشيك مقابل الوفاء أو بعضه بحيث أصبح الباقي لا يفي بقيمة الشيك. 

ج - إذا أمر المسحوب عليه بعدم دفع قيمة الشيك .

د - إذا تعمد تحرير الشيك أو التوقيع عليه بصورة تمنع صرفه.

هـ - إذا ظهر أو سلم شيكا وهو يعلم أنه ليس له مقابل يفي بقيمته أو أنه غير قابل للصرف.

و- إذا تلقى المستفيد أو الحامل شيكا لا يوجد له مقابل وفاء كاف لدفع قيمته.

فإذا عاد الجاني إلى ارتكاب أي من هذه الجرائم خلال ثلاث سنوات من تاريخ الحكم عليه في أي منها تكون العقوبة الحبس مدة لا تزيد على خمس سنوات والغرامة التي لا تزيد على مائة ألف ريال أو إحدى هاتين العقوبتين.','1989-04-18','مرسوم ملكي رقم م/45 وتاريخ 12/9/1409هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4763eb94-047b-46f1-9697-a9a700f1b7ed/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/45) وتاريخ 12 / 9 / 1409 هـ ، لتكون كما يلى :

مع مراعاة ما تقتضي به الأنظمة الأخرى، يعاقب بالحبس مدة لا تزيد على ثلاث سنوات وبغرامة لا تزيد على خمسين ألف ريال أو بإحدى هاتين العقوبتين كل من أقدم بسوء نية على ارتكاب أحد الأفعال الآتية:

أ - إذا سحب شيكا لا يكون له مقابل وفاء قائم وقابل للسحب أو يكون له مقابل وفاء أقل من قيمة الشيك.

ب - إذا استرد بعد إعطاء الشيك مقابل الوفاء أو بعضه بحيث أصبح الباقي لا يفي بقيمة الشيك. 

ج - إذا أمر المسحوب عليه بعدم د'),
('boe26-ef53b1412d3e414cc9a75365','cmpz65k7y04klcwg20qvmao6h','مع مراعاة ما تقضي به الأنظمة الأخرى، يعاقب بغرامة لا تزيد على مائة ألف ريال كل مسحوب عليه رفض بسوء نية وفاء شيك مسحوب سحبا صحيحا وله مقابل وفاء ولم تقدم بشأنه أية معارضة مع عدم الإخلال بالتعويض المستحق للساحب عما أصابه من ضرر بسبب عدم الوفاء.
ويعاقب بهذه العقوبة كل مسحوب عليه صرح عن علم بوجود مقابل وفاء هو أقل مما لديه فعلا.','1989-04-18','مرسوم ملكي رقم م/45 وتاريخ 12/9/1409هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4763eb94-047b-46f1-9697-a9a700f1b7ed/1','عدلت هذه المادة بموجب المرسوم الملكي رقم (م/45) وتاريخ 12 / 9 / 1409 هـ ، لتكون كما يلى :

مع مراعاة ما تقضي به الأنظمة الأخرى، يعاقب بغرامة لا تزيد على مائة ألف ريال كل مسحوب عليه رفض بسوء نية وفاء شيك مسحوب سحبا صحيحا وله مقابل وفاء ولم تقدم بشأنه أية معارضة مع عدم الإخلال بالتعويض المستحق للساحب عما أصابه من ضرر بسبب عدم الوفاء.
ويعاقب بهذه العقوبة كل مسحوب عليه صرح عن علم بوجود مقابل وفاء هو أقل مما لديه فعلا.'),
('boe26-66c318614d99728d6a120f4f','cmpzcv47909hqvtrkuv3hlxxt','يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية','2021-07-13','قرار مجلس الوزراء رقم 722 وتاريخ 1442/12/3هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/49ab78f2-a4ad-42f8-97ce-a9a700f28035/1','- عُدلت هذه المادة وذلك بموجب قرار مجلس الوزراء رقم (722) وتاريخ 1442/12/3هـ، لتصبح بالنص الآتي: "يخضع منسوبو الهيئة لأحكام نظام العمل ونظام التأمينات الاجتماعية".'),
('boe26-30924a895fec67d43a460027','cmpzcv47a09i9vtrk6iwr8tfn','يُمنح الترخيص للمختبرات بشرط التزام الترخيص بتوفير الكوادر اللازمة من المتخصصين المؤهلين علمياً، والمعدات والأجهزة اللازمة للعمل بالمختبر بما يتفق مع حجم العمل وطبيعته، وفقاً لما تحدده الجهة المختصة والمركز','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص لآتي: 

" يُمنح الترخيص للمختبرات بشرط التزام الترخيص بتوفير الكوادر اللازمة من المتخصصين المؤهلين علمياً، والمعدات والأجهزة اللازمة للعمل بالمختبر بما يتفق مع حجم العمل وطبيعته، وفقاً لما تحدده الجهة المختصة والمركز".'),
('boe26-45ec8a54bc5f9e8f8fc6cf13','cmpzcv47a09iavtrky7ff6fen','تحدد اللائحة التنفيذية فئات المختبرات والشروط اللازم توافرها لكل فئة، بناءً على توصية من المركز','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" تحدد اللائحة التنفيذية فئات المختبرات والشروط اللازم توافرها لكل فئة، بناءً على توصية من المركز".'),
('boe26-8eec732c245d87108092a4fd','cmpzcv47a09icvtrkkt0cowb5','يُعطى المرخص له مهلة لا تزيد على سنة ونصف تبدأ من تاريخ حصوله على الترخيص لإكمال الحصول على الاعتماد من المركز. وفي حال انقضاء المهلة دون الحصول على الاعتماد يعد الترخيص ملغياً','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" يُعطى المرخص له مهلة لا تزيد على سنة ونصف تبدأ من تاريخ حصوله على الترخيص لإكمال الحصول على الاعتماد من المركز. وفي حال انقضاء المهلة دون الحصول على الاعتماد يعد الترخيص ملغياً".'),
('boe26-dcac1abd8ff5dc641302e168','cmpzcv47a09idvtrkuqbounl4','أ- تصدر الجهة المختصة الترخيص للمختبر الخاص بعد تسديد رسم الترخيص، ومقداره خمسة آلاف (5000) ريال للمختبر الرئيس، وألفان وخمسمائة (2500) ريال لكل فرع.

ب- مدة صلاحية الترخيص خمس سنوات تبدأ من تاريخ المهلة الواردة في المادة (السادسة) من هذا النظام، ويُجدد بطلب من صاحب الشأن يقدمه إلى الجهة المختصة قبل ثلاثة أشهر على الأقل من تاريخ انتهاء مدته. ويكون التجديد من تاريخ انتهاء الترخيص','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" أ- تصدر الجهة المختصة الترخيص للمختبر الخاص بعد تسديد رسم الترخيص، ومقداره خمسة آلاف (5000) ريال للمختبر الرئيس، وألفان وخمسمائة (2500) ريال لكل فرع.

ب- مدة صلاحية الترخيص خمس سنوات تبدأ من تاريخ المهلة الواردة في المادة (السادسة) من هذا النظام، ويُجدد بطلب من صاحب الشأن يقدمه إلى الجهة المختصة قبل ثلاثة أشهر على الأقل من تاريخ انتهاء مدته. ويكون التجديد من تاريخ انتهاء الترخيص".'),
('boe26-8d7da5c68cee56ec604e892a','cmpzcv47a09ievtrk8luchk4j','تصدر الجهة المختصة قراراً بالسلع المزمع فحصها بواسطة المختبر الخاص قبل (ستين) يوماً من إسناد المهمة إلى المختبر الخاص، وبعد الإعلان عنها في الجريدة الرسمية، وتبلّغ هيئة الزكاة والضريبة والجمارك بذلك','2021-11-11','مرسوم ملكي رقم م/31 وتاريخ 1443/4/6هـ','https://laws.boe.gov.sa/BoeLaws/Laws/LawDetails/4c55f487-89fa-4d0f-80f1-a9a700f2835e/1','- عُدلت هذه المادة وذلك بموجب المرسوم الملكي رقم (م/31) وتاريخ 1443/4/6هـ، لتكون بالنص الآتي:

" تصدر الجهة المختصة قراراً بالسلع المزمع فحصها بواسطة المختبر الخاص قبل (ستين) يوماً من إسناد المهمة إلى المختبر الخاص، وبعد الإعلان عنها في الجريدة الرسمية، وتبلّغ هيئة الزكاة والضريبة والجمارك بذلك".')
